// Bluetooth lab B5 Phone app.  uv run pio run -d labs/ble-lab-b5 -e ble-lab-b5 -t upload
// Our own app instead of nRF Connect: esp-labs/apps/ble-app talks to the board with Web Bluetooth,
// straight from Chrome (Mac, Android) or Bluefy (iPhone). No Wi-Fi, no server. B3's Bench service
// stays as it was; B5 adds a sketch pad, live sensors, a speed test and link controls on top.
//
// Wiring: the screen from lesson 03. Optional: a jumper wire on GPIO 1 (touch its free end: the
// live view's touch line jumps). The push button on GPIO 5 is optional (it does what BOOT does).
//
// Views: sketch · live · speed · gatt · link · log   (click = next view, double-click = footer action)
// Every gesture is also sent to a subscribed app as a Button notification (B3's characteristic).
// Serial: help lists the commands. Shared code: kit/lib/ble-kit; B5's own characteristics: extras.h.
#include "b5_views.h"
#include "bench_views.h"
#include "ble_lab.h"
#include "server_link.h"

namespace {

// B3's link callbacks, plus: a new connection starts with no subscriptions.
class Links : public ble::ServerLink {
 public:
  void onConnect(NimBLEServer *s, NimBLEConnInfo &c) override;
};

Links links;
bench::BenchService bench_;
b5::Extras extras;
b5::Sketch sketchPad;
b5::Samples samples;
uint32_t sampleAt = 0;

void Links::onConnect(NimBLEServer *s, NimBLEConnInfo &c) {
  ble::ServerLink::onConnect(s, c);
  extras.resetSubscriptions();
}

// ---- Views ------------------------------------------------------------------------------------

void drawSketch(BleLab &lab, FrameBuffer &fb, float) { b5v::sketch(fb, sketchPad, extras.state(), lab.state().radio == ble::Radio::Connected); }
void drawLive(BleLab &, FrameBuffer &fb, float) { b5v::live(fb, samples, extras.state()); }
void drawSpeed(BleLab &, FrameBuffer &fb, float t) { b5v::speed(fb, extras.state(), t); }
void drawGatt(BleLab &, FrameBuffer &fb, float t) { bv::gatt(fb, bench_.state(), t); }
void drawLink(BleLab &lab, FrameBuffer &fb, float t) { bv::link(fb, lab.state(), t, "this board", "app"); }
void drawLog(BleLab &, FrameBuffer &fb, float) { bv::log(fb); }

const BleView kViews[] = {
    {"sketch", drawSketch, "clear"},
    {"live", drawLive, nullptr},
    {"speed", drawSpeed, "speed 50000"},
    {"gatt", drawGatt, "press"},
    {"link", drawLink, "params fast"},
    {"log", drawLog, nullptr},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdAdv(BleLab &lab, const String &, const String &lower) {
  if (lower != "on" && lower != "off") return lab.warn("adv on | adv off");
  if (lower == "on") return bench::advertise(lab.spec().deviceName);
  NimBLEDevice::getAdvertising()->stop();
  ble::link().edit([](ble::LinkState &s) {
    s.advertising = false;
    if (s.radio == ble::Radio::Advertising) s.radio = ble::Radio::Off;
  });
  BLE_NOTE(Info, "advertising off: invisible to phones");
}

void cmdClear(BleLab &lab, const String &, const String &) {
  sketchPad.clear();
  lab.showView("sketch");
  BLE_NOTE(Info, "sketch cleared");
}

void cmdSpeed(BleLab &lab, const String &arg, const String &lower) {
  if (lower == "stop") return extras.stopSpeed();
  long bytes = 0;
  if (!BleLab::number(arg, 1000, 1000000, bytes)) return lab.warn("speed <bytes> (1000-1000000) | speed stop");
  lab.showView("speed");
  extras.startSpeed(uint32_t(bytes));
}

void cmdPress(BleLab &, const String &, const String &) { bench_.button(1); }

void linkOp(BleLab &lab, uint8_t op) {
  const ble::LinkState s = ble::link().get();
  if (s.radio != ble::Radio::Connected) return lab.warn("connect the app first");
  NimBLEServer *server = NimBLEDevice::getServer();
  // Units: interval 1.25 ms, timeout 10 ms. The central (the phone or Mac) has the last word.
  switch (op) {
    case 1: server->updateConnParams(s.peer.handle, 6, 12, 0, 400); BLE_NOTE(Tx, "asked for 7.5-15 ms"); break;
    case 2: server->updateConnParams(s.peer.handle, 80, 160, 4, 600); BLE_NOTE(Tx, "asked for 100-200 ms, latency 4"); break;
    case 3: server->updatePhy(s.peer.handle, BLE_GAP_LE_PHY_2M_MASK, BLE_GAP_LE_PHY_2M_MASK, 0); BLE_NOTE(Tx, "asked for the 2M PHY"); break;
    case 4: server->updatePhy(s.peer.handle, BLE_GAP_LE_PHY_1M_MASK, BLE_GAP_LE_PHY_1M_MASK, 0); BLE_NOTE(Tx, "asked for the 1M PHY"); break;
    case 5:
      // Data Length Extension: link-layer packets of up to 251 bytes instead of 27, so one
      // 247-byte MTU packet no longer has to be cut into 10 radio packets.
      server->setDataLen(s.peer.handle, 251);
      BLE_NOTE(Tx, "asked for 251-byte radio packets");
      break;
  }
}

void cmdParams(BleLab &lab, const String &, const String &lower) {
  if (lower == "fast") return linkOp(lab, 1);
  if (lower == "slow") return linkOp(lab, 2);
  lab.warn("params fast | params slow   (the central may say no)");
}

void cmdPhy(BleLab &lab, const String &, const String &lower) {
  if (lower == "2m") return linkOp(lab, 3);
  if (lower == "1m") return linkOp(lab, 4);
  lab.warn("phy 1m | phy 2m");
}

void cmdDle(BleLab &lab, const String &, const String &) { linkOp(lab, 5); }

void cmdDisconnect(BleLab &lab, const String &, const String &) {
  const ble::LinkState s = ble::link().get();
  if (s.radio != ble::Radio::Connected) return lab.warn("nobody is connected");
  NimBLEDevice::getServer()->disconnect(s.peer.handle);
}

void cmdLed(BleLab &lab, const String &, const String &lower) {
  if (lower != "auto") return lab.warn("led auto: the LED shows the radio's state again");
  lab.claimLed(false);
  BLE_NOTE(Info, "LED shows the radio again");
}

const BleCommand kCommands[] = {
    {"adv", "on|off", "advertise (visible, connectable) or hide", cmdAdv},
    {"clear", "", "wipe the sketch", cmdClear},
    {"speed", "<bytes>|stop", "notify that many bytes to the app, as fast as it goes", cmdSpeed},
    {"params", "fast|slow", "ask the central for another connection interval", cmdParams},
    {"phy", "1m|2m", "ask for the 1M or 2M radio mode", cmdPhy},
    {"dle", "", "ask for 251-byte radio packets (data length extension)", cmdDle},
    {"press", "", "send a Button click notification", cmdPress},
    {"disconnect", "", "hang up on the app", cmdDisconnect},
    {"led", "auto", "after the app set the LED: show radio state again", cmdLed},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(BleLab &lab) {
  if (!sketchPad.begin()) BLE_NOTE(Bad, "no memory for the sketch buffer");
  NimBLEServer *server = NimBLEDevice::createServer();
  server->setCallbacks(&links, false);
  bench_.begin(server, bench::Options{});
  extras.begin(bench_.service());  // before start(): the GATT table is fixed once the server runs
  server->start();
  // Ask for the biggest ATT packet; the app's side decides the final MTU.
  NimBLEDevice::setMTU(247);
  bench::advertise(lab.spec().deviceName);
}

void tick(BleLab &lab) {
  bench_.tick();
  uint8_t c[3];
  if (bench_.takeLed(c)) {
    lab.claimLed(true);
    rgbLedWrite(PIN_RGB, c[0], c[1], c[2]);
  }
  // Draw what the app sent: at most 16 queued writes per frame.
  b5::CanvasWrite w;
  for (int i = 0; i < 16 && extras.takeCanvas(w); i++) {
    const canvas::Result r = sketchPad.apply(w.data, w.len);
    if (r.unknown) BLE_NOTE(Warn, "sketch: unknown command, rest of the write skipped");
    else if (r.truncated) BLE_NOTE(Warn, "sketch: a command was cut off");
  }
  if (const uint8_t op = extras.takeLinkOp()) linkOp(lab, op);
  if (const uint32_t bytes = extras.takeSpeedStart()) {
    lab.showView("speed");
    extras.startSpeed(bytes);
  }
  // Sensors every 200 ms: into the sparklines, and to the app if it subscribed.
  if (millis() - sampleAt >= 200) {
    sampleAt = millis();
    const float temp = temperatureRead();
    const uint32_t touch = touchRead(1);
    const uint32_t heap = ESP.getFreeHeap();
    const int8_t rssi = lab.state().radio == ble::Radio::Connected ? lab.state().peer.rssi : 0;
    samples.push(temp, float(touch), float(heap), float(rssi));
    extras.sendSensors(temp, touch, heap, rssi);
  }
}

bool gesture(BleLab &, Gesture g, bool) {
  bench_.button(g == Gesture::Click ? 1 : g == Gesture::DoubleClick ? 2 : 3);
  return false;
}

const BleLabSpec kSpec{
    "ble-lab-b5", "B5", "Phone app", "Bench B5", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, tick, gesture, nullptr,
};

BleLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// B5's own screens (320 x 170); gatt, link and log come from kit/lib/ble-kit:
//   sketch  what the app draws, live, plus how many commands and bytes arrived
//   live    the four sensor values the app charts, as sparklines over the last 12 s
//   speed   the speed test: a running transfer as packets flying, past runs as kB/s bars
#pragma once

#include "ble_views.h"
#include "extras.h"
#include "sketch.h"

namespace b5 {

// The last 60 sensor samples (one per 200 ms = 12 s).
struct Samples {
  static constexpr int kN = 60;
  float v[4][kN] = {};
  int head = 0;
  void push(float temp, float touch, float heap, float rssi) {
    const int i = head % kN;
    v[0][i] = temp, v[1][i] = touch, v[2][i] = heap, v[3][i] = rssi;
    head++;
  }
  float at(int s, int i) const { return head < kN ? v[s][i] : v[s][(head + i) % kN]; }
  int count() const { return head < kN ? head : kN; }
};

}  // namespace b5

namespace b5v {

using namespace bv;

inline void sketch(FrameBuffer &fb, b5::Sketch &sk, const b5::State &s, bool connected) {
  sk.blit(fb, 29);
  if (sk.commands() == 0) {
    bold(fb, 10, 70, pal::ink, connected ? "Draw in the app's Sketch tab" : "Open the ble-app, connect");
    small(fb, 10, 84, pal::muted, "Every stroke arrives as a write without response");
    small(fb, 10, 96, pal::muted, "to Canvas (ba5e0010) and lands here.");
  }
  char v[48];
  snprintf(v, sizeof(v), "%lu cmds %lu writes %lu B%s", static_cast<unsigned long>(sk.commands()), static_cast<unsigned long>(s.canvasWrites),
           static_cast<unsigned long>(s.canvasBytes), s.dropped ? " DROPPED" : "");
  fb.fillRect(0, 146, kW, 11, pal::night);
  small(fb, 6, 148, s.dropped ? pal::amber : pal::muted, v);
}

inline void sparkline(FrameBuffer &fb, int x, int y, int w, int h, const b5::Samples &sm, int series, uint16_t c) {
  const int n = sm.count();
  if (n < 2) return;
  float lo = sm.at(series, 0), hi = lo;
  for (int i = 1; i < n; i++) lo = std::min(lo, sm.at(series, i)), hi = std::max(hi, sm.at(series, i));
  if (hi - lo < 1e-3f) hi = lo + 1;
  int px = -1, py = 0;
  for (int i = 0; i < n; i++) {
    const int xx = x + i * (w - 1) / (b5::Samples::kN - 1);
    const int yy = y + h - 1 - int((sm.at(series, i) - lo) * (h - 1) / (hi - lo));
    if (px >= 0) fb.drawLine(px, py, xx, yy, c);
    px = xx, py = yy;
  }
  fb.fillCircle(px, py, 2, c);
}

inline void live(FrameBuffer &fb, const b5::Samples &sm, const b5::State &s) {
  static const char *const names[] = {"temperature", "touch GPIO 1", "free heap", "link RSSI"};
  static const uint16_t colours[] = {pal::amber, pal::teal, kViolet, kBlue};
  for (int k = 0; k < 4; k++) {
    const int y = 34 + k * 30;
    const float last = sm.count() ? sm.at(k, sm.count() - 1) : 0;
    char v[24];
    if (k == 0) snprintf(v, sizeof(v), "%.2f C", last);
    else if (k == 1) snprintf(v, sizeof(v), "%lu", static_cast<unsigned long>(last));
    else if (k == 2) snprintf(v, sizeof(v), "%lu kB", static_cast<unsigned long>(last / 1024));
    else snprintf(v, sizeof(v), last != 0 ? "%d dBm" : "-", int(last));
    small(fb, 6, y, pal::muted, names[k]);
    bold(fb, 6, y + 20, colours[k], v);
    fb.drawFastHLine(110, y + 24, 204, pal::dim);
    sparkline(fb, 110, y, 204, 24, sm, k, colours[k]);
  }
  char v[48];
  snprintf(v, sizeof(v), s.subscribed[b5::Sensors] ? "notifying the app: %lu sent" : "app not subscribed to Sensors (%lu sent)",
           static_cast<unsigned long>(s.sensorNotifies));
  small(fb, 110, 150 - 2, s.subscribed[b5::Sensors] ? pal::teal : pal::muted, v);
}

inline void speed(FrameBuffer &fb, const b5::State &s, float t) {
  if (s.running) {
    // A transfer in flight: packets streaming from the board (left) to the phone (right).
    small(fb, 6, 36, pal::amber, "sending...");
    fb.drawRoundRect(6, 50, 20, 30, 3, kBlue);
    fb.drawRoundRect(290, 46, 22, 38, 4, pal::muted);
    for (int i = 0; i < 8; i++) {
      const float k = fmodf(t * 2.0f + i / 8.0f, 1.0f);
      fb.fillRect(30 + int(k * 252), 62, 6, 6, mix(kViolet, pal::night, uint8_t(k * 120)));
    }
    const uint32_t pct = s.target ? s.sent * 100 / s.target : 0;
    fb.drawRect(6, 92, 308, 8, pal::dim);
    fb.fillRect(7, 93, int(306 * pct / 100), 6, kViolet);
    char v[56];
    const uint32_t ms = std::max<uint32_t>(millis() - s.startedAt, 1);
    snprintf(v, sizeof(v), "%lu / %lu B  %.1f kB/s  %lu waits", static_cast<unsigned long>(s.sent), static_cast<unsigned long>(s.target),
             s.sent / float(ms), static_cast<unsigned long>(s.retries));
    small(fb, 6, 106, pal::ink, v);
    small(fb, 6, 120, pal::muted, "A wait = the stack's buffers were full:");
    small(fb, 6, 130, pal::muted, "the radio sends only in connection events.");
    return;
  }
  const int shown = std::min(s.runCount, 6);
  if (shown == 0) {
    bold(fb, 6, 60, pal::ink, "No speed runs yet");
    small(fb, 6, 74, pal::muted, "App: Speed tab, Run. Or serial: speed 50000");
    small(fb, 6, 86, pal::muted, "(the app must subscribe to Speed first).");
    small(fb, 6, 104, pal::muted, "kB/s ~ (MTU - 3) x packets per event / interval");
    return;
  }
  float peak = 1;
  for (int i = 0; i < shown; i++) peak = std::max(peak, s.runs[(s.runCount - shown + i) % 6].kBps());
  static const char *const phy[] = {"?", "1M", "2M", "Cd"};
  for (int i = 0; i < shown; i++) {
    const b5::SpeedRun &r = s.runs[(s.runCount - shown + i) % 6];
    const int y = 36 + i * 20;
    const int w = int(r.kBps() * 150 / peak);
    fb.fillRect(6, y, std::max(w, 1), 12, i == shown - 1 ? kViolet : mix(kViolet, pal::night, 110));
    char v[48];
    snprintf(v, sizeof(v), "%.1f kB/s", r.kBps());
    small(fb, 10 + std::max(w, 1), y + 2, pal::ink, v);
    snprintf(v, sizeof(v), "MTU %u %.1fms %s", r.mtu, r.interval * 1.25f, phy[r.phy & 3]);
    small(fb, 216, y + 2, pal::muted, v);
  }
}

}  // namespace b5v

// B5's own characteristics, added to the Bench service from B3 (same UUID base, 0010 and up):
//
//   Canvas   ...0010  write without response   the sketch protocol (canvas_protocol.h)
//   Sensors  ...0011  read, notify             every 200 ms while subscribed, 12 bytes:
//                                              int16 temperature x 100 · uint32 touch (GPIO 1) ·
//                                              uint32 free heap · int8 RSSI (dBm) · uint8 sequence
//   Speed    ...0012  write, notify            write 01 + uint32 bytes: the board notifies that many
//                                              bytes as fast as it can, in packets of MTU - 3 bytes
//                                              starting with a uint16 sequence number. Then one
//                                              summary packet: FF FF · uint32 bytes · uint32 ms ·
//                                              uint16 MTU · uint16 interval (1.25 ms units) · uint8 PHY.
//                                              Write 00 to stop early.
//   Link     ...0013  write                    one byte: 1 fast interval · 2 slow interval ·
//                                              3 2M PHY · 4 1M PHY · 5 longer link-layer packets (251 B)
//
// The NimBLE task only copies bytes into queues here. loop() draws the sketch (tick), and the
// speed test has its own small task that pushes notifications until the stack's buffers are full.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <freertos/queue.h>

#include "bench_service.h"
#include "ble_link.h"
#include "server_link.h"

namespace b5 {

enum Chr : uint8_t { Canvas, Sensors, Speed, LinkOps, kCount };

inline const char *chrName(int c) {
  static const char *const names[] = {"Canvas", "Sensors", "Speed", "Link"};
  return names[c];
}

// One write to the Canvas characteristic, waiting for loop().
struct CanvasWrite {
  uint8_t len;
  uint8_t data[244];  // the largest write that fits one 247-byte MTU
};

// One finished speed run, for the speed view.
struct SpeedRun {
  uint32_t bytes = 0, ms = 0, retries = 0;
  uint16_t mtu = 0, interval = 0;
  uint8_t phy = 1;
  float kBps() const { return ms ? bytes / float(ms) : 0; }  // bytes per ms = kB/s
};

// What the views show: copied under the lock.
struct State {
  bool subscribed[kCount] = {};
  uint32_t canvasWrites = 0, canvasBytes = 0, dropped = 0;
  bool running = false;
  uint32_t target = 0, sent = 0, startedAt = 0, retries = 0;
  SpeedRun runs[6];
  int runCount = 0;  // total ever; runs[] keeps the last 6
  uint32_t sensorNotifies = 0;
};

class Extras : public NimBLECharacteristicCallbacks {
 public:
  void begin(NimBLEService *svc) {
    queue_ = xQueueCreate(16, sizeof(CanvasWrite));
    chr_[Canvas] = svc->createCharacteristic(bench::uuid(0x10), NIMBLE_PROPERTY::WRITE_NR | NIMBLE_PROPERTY::WRITE, 244);
    describe(chr_[Canvas], "Canvas: sketch commands");
    chr_[Sensors] = svc->createCharacteristic(bench::uuid(0x11), NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY, 12);
    describe(chr_[Sensors], "Sensors: temp, touch, heap, RSSI");
    chr_[Speed] = svc->createCharacteristic(bench::uuid(0x12), NIMBLE_PROPERTY::WRITE | NIMBLE_PROPERTY::NOTIFY, 244);
    describe(chr_[Speed], "Speed test");
    chr_[LinkOps] = svc->createCharacteristic(bench::uuid(0x13), NIMBLE_PROPERTY::WRITE, 1);
    describe(chr_[LinkOps], "Link: 1 fast 2 slow 3 2M 4 1M 5 DLE");
    for (auto *c : chr_) c->setCallbacks(this);
    uint8_t zero[12] = {};
    chr_[Sensors]->setValue(zero, sizeof(zero));
  }

  // ---- loop() side ----------------------------------------------------------------------------

  // Next queued Canvas write, if any.
  bool takeCanvas(CanvasWrite &w) { return queue_ && xQueueReceive(queue_, &w, 0) == pdTRUE; }

  // Pending Link operation (0 = none), taken once.
  uint8_t takeLinkOp() {
    portENTER_CRITICAL(&lock_);
    const uint8_t op = linkOp_;
    linkOp_ = 0;
    portEXIT_CRITICAL(&lock_);
    return op;
  }

  // Pending speed start (bytes) or 0; taken once.
  uint32_t takeSpeedStart() {
    portENTER_CRITICAL(&lock_);
    const uint32_t b = speedStart_;
    speedStart_ = 0;
    portEXIT_CRITICAL(&lock_);
    return b;
  }

  // Build and (if subscribed) notify the 12-byte sensors packet.
  void sendSensors(float tempC, uint32_t touch, uint32_t heap, int8_t rssi) {
    uint8_t p[12];
    const int16_t t = int16_t(tempC * 100);
    memcpy(p, &t, 2);
    memcpy(p + 2, &touch, 4);
    memcpy(p + 6, &heap, 4);
    p[10] = uint8_t(rssi);
    p[11] = seq_++;
    chr_[Sensors]->setValue(p, sizeof(p));
    if (!subscribed(Sensors)) return;
    if (chr_[Sensors]->notify()) {
      ble::countTx(sizeof(p));
      portENTER_CRITICAL(&lock_);
      state_.sensorNotifies++;
      portEXIT_CRITICAL(&lock_);
    }
  }

  // Start a speed run in its own task. False when one is running or nobody listens.
  bool startSpeed(uint32_t bytes) {
    const ble::LinkState s = ble::link().get();
    if (s.radio != ble::Radio::Connected) return BLE_NOTE(Warn, "speed: connect first"), false;
    if (!subscribed(Speed)) return BLE_NOTE(Warn, "speed: subscribe to Speed (ba5e0012) first"), false;
    portENTER_CRITICAL(&lock_);
    const bool busy = state_.running;
    if (!busy) {
      state_.running = true;
      state_.target = bytes;
      state_.sent = 0;
      state_.retries = 0;
      state_.startedAt = millis();
      stopRequested_ = false;
    }
    portEXIT_CRITICAL(&lock_);
    if (busy) return BLE_NOTE(Warn, "speed: a run is already going"), false;
    run_ = SpeedRun{};
    run_.mtu = s.peer.mtu;
    run_.interval = s.peer.interval;
    run_.phy = s.peer.txPhy;
    handle_ = s.peer.handle;
    BLE_NOTE(Tx, "speed: %lu bytes in %u-byte packets", static_cast<unsigned long>(bytes), s.peer.mtu - 3);
    // Core 1 at priority 1, like loop(): the NimBLE host on core 0 keeps its own pace.
    if (xTaskCreatePinnedToCore(speedTask, "speed", 4096, this, 1, nullptr, 1) != pdPASS) {
      portENTER_CRITICAL(&lock_);
      state_.running = false;
      portEXIT_CRITICAL(&lock_);
      return BLE_NOTE(Bad, "speed: no memory for the task"), false;
    }
    return true;
  }

  void stopSpeed() {
    portENTER_CRITICAL(&lock_);
    stopRequested_ = true;
    portEXIT_CRITICAL(&lock_);
  }

  State state() {
    portENTER_CRITICAL(&lock_);
    State s = state_;
    portEXIT_CRITICAL(&lock_);
    return s;
  }

  // ---- NimBLE callbacks (NimBLE task) ---------------------------------------------------------

  void onWrite(NimBLECharacteristic *c, NimBLEConnInfo &) override {
    const NimBLEAttValue v = c->getValue();
    ble::countRx(v.size());
    if (c == chr_[Canvas]) {
      CanvasWrite w;
      w.len = uint8_t(std::min<size_t>(v.size(), sizeof(w.data)));
      memcpy(w.data, v.data(), w.len);
      const bool queued = xQueueSend(queue_, &w, 0) == pdTRUE;
      portENTER_CRITICAL(&lock_);
      state_.canvasWrites++;
      state_.canvasBytes += w.len;
      if (!queued) state_.dropped++;
      portEXIT_CRITICAL(&lock_);
      // No activity line per stroke: a sketch sends ~30 writes a second.
    } else if (c == chr_[Speed]) {
      if (v.size() >= 5 && v.data()[0] == 0x01) {
        uint32_t bytes;
        memcpy(&bytes, v.data() + 1, 4);
        bytes = std::max<uint32_t>(1000, std::min<uint32_t>(bytes, 1'000'000));
        portENTER_CRITICAL(&lock_);
        speedStart_ = bytes;
        portEXIT_CRITICAL(&lock_);
        BLE_NOTE(Rx, "write Speed: start %lu bytes", static_cast<unsigned long>(bytes));
      } else if (v.size() >= 1 && v.data()[0] == 0x00) {
        stopSpeed();
        BLE_NOTE(Rx, "write Speed: stop");
      } else {
        BLE_NOTE(Warn, "Speed wants 01 + uint32, or 00");
      }
    } else if (c == chr_[LinkOps]) {
      if (v.size() != 1 || v.data()[0] < 1 || v.data()[0] > 5) return BLE_NOTE(Warn, "Link wants one byte, 1-5");
      portENTER_CRITICAL(&lock_);
      linkOp_ = v.data()[0];
      portEXIT_CRITICAL(&lock_);
      BLE_NOTE(Rx, "write Link: %u", v.data()[0]);
    }
  }

  void onSubscribe(NimBLECharacteristic *c, NimBLEConnInfo &, uint16_t subValue) override {
    for (int i = 0; i < kCount; i++)
      if (chr_[i] == c) {
        portENTER_CRITICAL(&lock_);
        state_.subscribed[i] = subValue != 0;
        portEXIT_CRITICAL(&lock_);
        BLE_NOTE(Rx, "%s %s", subValue ? "subscribe" : "unsubscribe", chrName(i));
      }
  }

  // A new connection starts with nobody subscribed.
  void resetSubscriptions() {
    portENTER_CRITICAL(&lock_);
    for (bool &s : state_.subscribed) s = false;
    portEXIT_CRITICAL(&lock_);
  }

 private:
  static void describe(NimBLECharacteristic *c, const char *text) {
    c->createDescriptor("2901", NIMBLE_PROPERTY::READ, strlen(text))->setValue(text);
  }

  bool subscribed(Chr c) {
    portENTER_CRITICAL(&lock_);
    const bool s = state_.subscribed[c];
    portEXIT_CRITICAL(&lock_);
    return s;
  }

  // The speed test. notify() fails when the stack's buffers are full (the radio hasn't sent the
  // earlier packets yet); we wait one tick and try again. That back-pressure IS the throughput.
  static void speedTask(void *arg) {
    auto *self = static_cast<Extras *>(arg);
    const uint32_t start = millis();
    const size_t size = std::min<size_t>(self->run_.mtu - 3, 244);
    uint8_t buf[244];
    uint16_t seq = 0;
    uint32_t sent = 0, retries = 0;
    for (;;) {
      portENTER_CRITICAL(&self->lock_);
      const bool stop = self->stopRequested_;
      const uint32_t target = self->state_.target;
      portEXIT_CRITICAL(&self->lock_);
      if (stop || sent >= target || ble::link().get().radio != ble::Radio::Connected) break;
      const size_t n = std::min<size_t>(size, std::max<uint32_t>(target - sent, 2));
      buf[0] = uint8_t(seq), buf[1] = uint8_t(seq >> 8);
      memset(buf + 2, uint8_t(seq), n - 2);
      if (self->chr_[Speed]->notify(buf, n, self->handle_)) {
        sent += n;
        seq = seq == 0xFFFE ? 0 : seq + 1;  // FF FF is kept for the summary
        if ((seq & 15) == 0) {
          portENTER_CRITICAL(&self->lock_);
          self->state_.sent = sent;
          self->state_.retries = retries;
          portEXIT_CRITICAL(&self->lock_);
        }
      } else {
        retries++;
        vTaskDelay(1);
      }
    }
    const uint32_t ms = std::max<uint32_t>(millis() - start, 1);
    SpeedRun r = self->run_;
    r.bytes = sent;
    r.ms = ms;
    r.retries = retries;
    // The summary, so the app can compare its own clock with ours.
    uint8_t sum[15] = {0xFF, 0xFF};
    memcpy(sum + 2, &sent, 4);
    memcpy(sum + 6, &ms, 4);
    memcpy(sum + 10, &r.mtu, 2);
    memcpy(sum + 12, &r.interval, 2);
    sum[14] = r.phy;
    for (int i = 0; i < 50 && !self->chr_[Speed]->notify(sum, sizeof(sum), self->handle_); i++) vTaskDelay(2);
    ble::link().edit([&](ble::LinkState &s) { s.txOps += sent / size, s.txBytes += sent; });
    portENTER_CRITICAL(&self->lock_);
    self->state_.running = false;
    self->state_.sent = sent;
    self->state_.runs[self->state_.runCount % 6] = r;
    self->state_.runCount++;
    portEXIT_CRITICAL(&self->lock_);
    BLE_NOTE(Good, "speed: %lu B in %lu ms = %.1f kB/s", static_cast<unsigned long>(sent), static_cast<unsigned long>(ms), r.kBps());
    vTaskDelete(nullptr);
  }

  NimBLECharacteristic *chr_[kCount] = {};
  QueueHandle_t queue_ = nullptr;
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  State state_;
  SpeedRun run_;
  uint16_t handle_ = 0xFFFF;
  uint8_t linkOp_ = 0, seq_ = 0;
  uint32_t speedStart_ = 0;
  bool stopRequested_ = false;
};

}  // namespace b5

// The sketch view's own picture: 320 x 128 pixels that only the app draws on. It lives in its own
// frame buffer, so every screen frame copies it under the status bar instead of redrawing strokes.
#pragma once

#include <math.h>

#include "canvas_protocol.h"
#include "color.h"
#include "frame_buffer.h"

namespace b5 {

class Sketch {
 public:
  Sketch() : fb_(canvas::kW, canvas::kH) {}

  bool begin() {
    if (!fb_.begin()) return false;
    fb_.fillScreen(pal::night);
    return true;
  }

  // Draw one write's commands. Returns what the parser found.
  canvas::Result apply(const uint8_t *p, size_t n) {
    Drawer d{fb_};
    const canvas::Result r = canvas::parse(p, n, d);
    commands_ += r.commands;
    if (r.truncated || r.unknown) errors_++;
    return r;
  }

  void clear() { fb_.fillScreen(pal::night); }

  // Copy into the screen's frame buffer at row y0 (under the header).
  void blit(FrameBuffer &screen, int y0) const {
    uint16_t *dst = screen.pixels();
    const uint16_t *src = const_cast<FrameBuffer &>(fb_).pixels();
    for (int y = 0; y < canvas::kH && y0 + y < screen.height(); y++)
      memcpy(dst + (y0 + y) * screen.width(), src + y * canvas::kW, canvas::kW * sizeof(uint16_t));
  }

  uint32_t commands() const { return commands_; }
  uint32_t errors() const { return errors_; }
  bool ready() { return fb_.pixels() != nullptr; }

 private:
  struct Drawer {
    FrameBuffer &fb;
    void clear(uint16_t c) { fb.fillScreen(c); }
    // A thick line = a row of filled circles along each segment.
    void stroke(uint16_t c, uint8_t w, const canvas::Point *pts, int n) {
      const int r = w / 2;
      if (n == 1) return dot(c, pts[0].x, pts[0].y, std::max(r, 1));
      for (int i = 1; i < n; i++) {
        if (r <= 0) {
          fb.drawLine(pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y, c);
          continue;
        }
        const float dx = pts[i].x - pts[i - 1].x, dy = pts[i].y - pts[i - 1].y;
        const int steps = std::max(1, int(sqrtf(dx * dx + dy * dy) / std::max(1, r / 2)));
        for (int s = 0; s <= steps; s++) fb.fillCircle(pts[i - 1].x + int(dx * s / steps), pts[i - 1].y + int(dy * s / steps), r, c);
      }
    }
    void rect(uint16_t c, int16_t x, int16_t y, int16_t w, int16_t h) { fb.fillRect(x, y, w, h, c); }
    void text(uint16_t c, int16_t x, int16_t y, uint8_t size, const char *s, uint8_t len) {
      fb.setFont(nullptr);
      fb.setTextSize(std::max<uint8_t>(1, std::min<uint8_t>(size, 4)));
      fb.setTextColor(c);
      fb.setCursor(x, y);
      for (int i = 0; i < len; i++) fb.write(uint8_t(s[i]) >= 0x20 && uint8_t(s[i]) < 0x7F ? s[i] : '?');
      fb.setTextSize(1);
    }
    void dot(uint16_t c, int16_t x, int16_t y, uint8_t r) { fb.fillCircle(x, y, r, c); }
  };

  FrameBuffer fb_;
  uint32_t commands_ = 0, errors_ = 0;
};

}  // namespace b5

// The sketch protocol: how the app draws on the board's screen over one characteristic.
// No Arduino and no radio here, so labs/ble-lab-b5/test/host/b5_canvas_test.cpp checks it on the Mac.
//
// The app writes to the Canvas characteristic (ba5e0010) "without response": the fastest kind of
// write, because the board never answers each one. One write can carry several commands back to
// back, up to MTU - 3 bytes. The drawing area is the screen under the status bar: 320 x 128 pixels,
// x 0-319, y 0-127. Colours are RGB565 (5 bits red, 6 green, 5 blue), the screen's own format.
// Every number is little-endian.
//
//   01 cc cc                              clear          the whole area with colour cc cc
//   02 cc cc w n [xx xx yy] x n           stroke         n points (1-80), joined by lines w px wide
//   03 cc cc xx xx yy ww ww hh            rect           a filled rectangle
//   04 cc cc xx xx yy s len [text]        text           len ASCII bytes, size s (1-4) at x, y (top left)
//   05 cc cc xx xx yy r                   dot            a filled circle, radius r
//
// Example: a red dot (F800) at x 160, y 64, radius 6. The bytes are 05, the colour little-endian
// (00 F8), x 00A0 little-endian (A0 00), y 40, r 06:
//   05 00 F8 A0 00 40 06
#pragma once

#include <stddef.h>
#include <stdint.h>

namespace canvas {

constexpr int kW = 320, kH = 128;
constexpr int kMaxPoints = 80;

enum Op : uint8_t { Clear = 0x01, Stroke = 0x02, Rect = 0x03, Text = 0x04, Dot = 0x05 };

struct Point {
  int16_t x;
  int16_t y;
};

// What a parse found: commands drawn, and whether the write ended in the middle of a command.
struct Result {
  int commands = 0;
  bool truncated = false;  // a command ran past the end of the write: the rest is ignored
  bool unknown = false;    // an opcode we don't know: the rest is ignored
};

inline uint16_t le16(const uint8_t *p) { return uint16_t(p[0] | (p[1] << 8)); }

// Walks one write and calls the drawer for each command. Drawer needs:
//   clear(c) · stroke(c, width, points, n) · rect(c, x, y, w, h) · text(c, x, y, size, chars, len) · dot(c, x, y, r)
template <typename Drawer>
Result parse(const uint8_t *p, size_t n, Drawer &d) {
  Result r;
  size_t i = 0;
  while (i < n) {
    const uint8_t op = p[i];
    const size_t left = n - i;
    switch (op) {
      case Clear:
        if (left < 3) return r.truncated = true, r;
        d.clear(le16(p + i + 1));
        i += 3;
        break;
      case Stroke: {
        if (left < 5) return r.truncated = true, r;
        const uint8_t count = p[i + 4];
        if (count == 0 || count > kMaxPoints || left < 5 + size_t(count) * 3) return r.truncated = true, r;
        Point pts[kMaxPoints];
        for (int k = 0; k < count; k++) {
          const uint8_t *q = p + i + 5 + k * 3;
          pts[k] = Point{int16_t(le16(q)), int16_t(q[2])};
        }
        d.stroke(le16(p + i + 1), p[i + 3], pts, count);
        i += 5 + count * 3;
        break;
      }
      case Rect:
        if (left < 10) return r.truncated = true, r;
        d.rect(le16(p + i + 1), int16_t(le16(p + i + 3)), int16_t(p[i + 5]), int16_t(le16(p + i + 6)), int16_t(p[i + 8]));
        i += 10;
        break;
      case Text: {
        if (left < 8) return r.truncated = true, r;
        const uint8_t len = p[i + 7];
        if (left < 8 + size_t(len)) return r.truncated = true, r;
        d.text(le16(p + i + 1), int16_t(le16(p + i + 3)), int16_t(p[i + 5]), p[i + 6], reinterpret_cast<const char *>(p + i + 8), len);
        i += 8 + len;
        break;
      }
      case Dot:
        if (left < 7) return r.truncated = true, r;
        d.dot(le16(p + i + 1), int16_t(le16(p + i + 3)), int16_t(p[i + 5]), p[i + 6]);
        i += 7;
        break;
      default: return r.unknown = true, r;
    }
    r.commands++;
  }
  return r;
}

}  // namespace canvas

// Screens for the Bench service (B3, B4, B5):
//   gatt     the service as a table, one row per characteristic, with its properties and value.
//            Every operation lights its row and sends a packet across: in from the phone for a
//            read or write, out to the phone for a notify. Subscribed rows carry a bell.
//   message  the last message written from the phone, big, and the LED's colour
#pragma once

#include <Fonts/FreeSansBold12pt7b.h>

#include "bench_service.h"
#include "ble_views.h"

namespace bv {

inline uint16_t opColour(bench::Op op) {
  switch (op) {
    case bench::Op::Read: return pal::teal;
    case bench::Op::Write: return kBlue;
    case bench::Op::Notify: return kViolet;
    case bench::Op::Subscribe: return pal::amber;
    case bench::Op::Denied: return pal::coral;
    default: return pal::dim;
  }
}

inline const char *opName(bench::Op op) {
  static const char *const names[] = {"", "read", "write", "notify", "subscribe", "refused"};
  return names[static_cast<int>(op)];
}

inline void bell(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.fillRoundRect(x, y, 7, 6, 2, c);
  fb.drawFastHLine(x - 1, y + 6, 9, c);
  fb.fillCircle(x + 3, y + 8, 1, c);
}

inline void gatt(FrameBuffer &fb, const bench::State &s, float t) {
  const uint32_t now = millis();
  small(fb, 6, 34, pal::muted, "Bench service ba5e0000-...");
  // The phone, on the right edge.
  const int px = 292, py = 92;
  fb.drawRoundRect(px, py - 26, 22, 44, 4, pal::muted);
  fb.fillRect(px + 8, py + 13, 6, 2, pal::muted);
  struct Row {
    bench::Chr c;
    const char *props;
  };
  const Row rows[] = {{bench::Led, "R W"}, {bench::Message, "R W"}, {bench::ButtonChr, "R N"}, {bench::Temperature, "R N"}, {bench::Uptime, "R"}, {bench::Vault, "R W lock"}};
  const int count = s.hasVault ? 6 : 5;
  for (int i = 0; i < count; i++) {
    const int y = 46 + i * 18;
    const bench::Chr c = rows[i].c;
    const uint32_t age = now - s.opAt[c];
    const bool hot = s.opAt[c] && age < 900;
    const uint16_t oc = opColour(s.op[c]);
    fb.fillRoundRect(4, y - 2, 238, 16, 3, hot ? mix(oc, kPanel, uint8_t(age * 255 / 900)) : kPanel);
    small(fb, 10, y + 2, pal::ink, bench::chrName(c));
    small(fb, 84, y + 2, pal::muted, rows[i].props);
    if (s.subscribed[c]) bell(fb, 126, y + 1, pal::amber);
    char v[24] = "";
    switch (c) {
      case bench::Led:
        snprintf(v, sizeof(v), "%02X %02X %02X", s.led[0], s.led[1], s.led[2]);
        fb.fillRect(222, y + 1, 14, 10, rgb(s.led[0], s.led[1], s.led[2]));
        fb.drawRect(222, y + 1, 14, 10, pal::muted);
        break;
      case bench::Message: snprintf(v, sizeof(v), "\"%.14s\"", s.message); break;
      case bench::ButtonChr: snprintf(v, sizeof(v), "#%u", s.buttonCount); break;
      case bench::Temperature: snprintf(v, sizeof(v), "%.2f C", s.tempC); break;
      case bench::Uptime: snprintf(v, sizeof(v), "%lus", static_cast<unsigned long>(now / 1000)); break;
      case bench::Vault: snprintf(v, sizeof(v), "%s", "encrypted"); break;
      default: break;
    }
    small(fb, 140, y + 2, hot ? pal::ink : pal::muted, v);
    // The packet in flight: from the phone into the row (read request, write, subscribe) or out of
    // the row to the phone (notify). 600 ms for the trip, so the eye can follow it.
    if (hot && age < 600) {
      const float k = age / 600.0f;
      const bool out = s.op[c] == bench::Op::Notify;
      const int x0 = 244, x1 = px - 2;
      const int x = out ? x0 + int(k * (x1 - x0)) : x1 - int(k * (x1 - x0));
      const int yy = y + 6 + int((py - y - 6) * (out ? k : 1 - k));
      fb.fillCircle(x, yy, 3, oc);
      small(fb, 248, y + 2, oc, opName(s.op[c]));
    }
  }
  (void)t;
}

inline void message(FrameBuffer &fb, const bench::State &s, float t) {
  const uint16_t led = rgb(s.led[0], s.led[1], s.led[2]);
  // The LED as a glowing disc.
  for (int r = 26; r > 0; r -= 2) fb.fillCircle(270, 96, r, mix(pal::night, led, uint8_t(255 - r * 8)));
  small(fb, 246, 134, pal::muted, s.ledWritten ? "LED from phone" : "LED: write 0001");
  if (!s.message[0]) {
    bold(fb, 10, 70, pal::ink, "Write a message");
    small(fb, 10, 84, pal::muted, "to characteristic ba5e0002 in nRF Connect");
    small(fb, 10, 96, pal::muted, "or LightBlue (UTF-8 text, up to 40 bytes)");
    return;
  }
  // Wrap the message over up to three lines of 12 pt.
  fb.setFont(&FreeSansBold12pt7b);
  fb.setTextColor(pal::ink);
  const char *p = s.message;
  int y = 66;
  char line[41];
  while (*p && y < 140) {
    int take = 0, lastSpace = -1;
    while (p[take]) {
      strlcpy(line, p, take + 2);
      if (textWidth(fb, line) > 220) break;
      if (p[take] == ' ') lastSpace = take;
      take++;
    }
    if (p[take] && lastSpace > 0) take = lastSpace + 1;
    strlcpy(line, p, take + 1);
    fb.setCursor(10, y);
    fb.print(line);
    p += take;
    y += 28;
  }
  const uint32_t age = (millis() - s.messageAt) / 1000;
  char v[32];
  snprintf(v, sizeof(v), "written %lus ago", static_cast<unsigned long>(age));
  small(fb, 10, 146, pal::muted, v);
  (void)t;
}

}  // namespace bv

// The shell every Bluetooth LE lab (B1-B8) shares: the screen with its status bar, the push button
// and BOOT, the on-board LED, serial commands, and printing the activity log.
//
// A lab is a BleLabSpec: its views (each one a draw function, plus what a double-click does there),
// its serial commands, and three hooks: setup() once NimBLE is running, tick() on every loop, and
// gesture() to give the button a lab-specific meaning. Each src/ble-lab-bN/main.cpp is that list.
//
// Button or BOOT, by default: click = next view · double-click = this view's action · long press =
// the lab's long action. While a numeric comparison waits: click = yes, long press = no.
// On-board LED, unless the lab claims it: breathing blue = advertising · cyan pulse = scanning ·
// steady blue = connected · violet = encrypted · amber blink = a passkey waits · white blink = data.
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "ble_views.h"
#include "button.h"
#include "display.h"
#include "pins.h"

class BleLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct BleCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dBm>"
  const char *what;  // one line for help
  void (*run)(BleLab &lab, const String &arg, const String &lower);
};

struct BleView {
  const char *name;  // "radar"
  void (*draw)(BleLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct BleLabSpec {
  const char *env;         // "ble-lab-b1"
  const char *id;          // "B1"
  const char *title;       // "Listen"
  const char *deviceName;  // what phones see: "Bench B3"
  const BleView *views;
  int viewCount;
  int startView;
  const BleCommand *commands;
  int commandCount;
  void (*setup)(BleLab &lab) = nullptr;  // after NimBLE is initialised
  void (*tick)(BleLab &lab) = nullptr;   // every loop, before drawing
  // First say on every gesture. Return true when handled, false for the default.
  bool (*gesture)(BleLab &lab, Gesture g, bool external) = nullptr;
  const char *longAction = nullptr;  // the command line a long press runs by default
};

class BleLab {
 public:
  explicit BleLab(const BleLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    if (!NimBLEDevice::init(spec_.deviceName)) {
      log_e("NimBLE did not start. Stopping.");
      return;
    }
    Serial.printf("\n%s: NimBLE %s up, address %s, TX power %d dBm\n", spec_.env, NimBLEDevice::getVersion(),
                  NimBLEDevice::getAddress().toString().c_str(), NimBLEDevice::getPower());
    if (spec_.setup) spec_.setup(*this);
    printHelp();
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    measureRssi();
    if (spec_.tick) spec_.tick(*this);
    link_ = ble::link().get();
    printActivity();
    showLed();

    const float t = millis() / 1000.0f;
    const BleView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    if (passkeyShowing()) bv::passkey(fb, link_, t);
    bv::header(fb, spec_.id, v.name, view_, spec_.viewCount, link_, t);
    char hint[40];
    if (passkeyShowing() && link_.passkeyCompare) snprintf(hint, sizeof(hint), "click = yes, long = no");
    else if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    bv::footer(fb, hint);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  const ble::LinkState &state() const { return link_; }
  const BleLabSpec &spec() const { return spec_; }
  int view() const { return view_; }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself (B3's LED characteristic); false hands it back.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[120];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  // Parse a number argument; false when it is missing, not a number or out of range.
  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "power") return power(arg);
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  bool passkeyShowing() const { return link_.passkey != 0 && millis() - link_.passkeySince < 30000; }

  void printHelp() {
    Serial.printf("\nBluetooth lab %s %s  (%s)  ·  phones see \"%s\"\n", spec_.id, spec_.title, spec_.env, spec_.deviceName);
    for (int i = 0; i < spec_.commandCount; i++) {
      const BleCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "status", "the radio, the link and its security, in detail");
    Serial.printf("  %-28s %s\n", "power <dBm>", "transmit power: -24 to 20 (default 9)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const ble::LinkState s = ble::link().get();
    Serial.printf("radio %s · this board %s · TX power %d dBm\n", ble::radioName(s.radio), NimBLEDevice::getAddress().toString().c_str(),
                  NimBLEDevice::getPower());
    if (s.radio != ble::Radio::Connected) {
      if (s.lastDisconnect >= 0) Serial.printf("last link ended: 0x%02X %s\n", s.lastDisconnect & 0xFF, ble::disconnectReason(s.lastDisconnect));
      return;
    }
    const ble::Peer &p = s.peer;
    Serial.printf("peer %s%s%s (%s) · we are the %s\n", p.addr, p.idAddr[0] ? " id " : "", p.idAddr, p.name[0] ? p.name : "no name",
                  p.central ? "peripheral" : "central");
    Serial.printf("interval %.2f ms · latency %u · timeout %u ms · MTU %u · PHY %u/%u · RSSI %d dBm\n", p.interval * 1.25f, p.latency,
                  p.timeout * 10, p.mtu, p.txPhy, p.rxPhy, p.rssi);
    Serial.printf("security: %s, %s, %s, key %u bytes\n", p.encrypted ? "encrypted" : "not encrypted",
                  p.authenticated ? "authenticated (MITM)" : "not authenticated", p.bonded ? "bonded" : "not bonded", p.keySize);
    Serial.printf("traffic: rx %lu ops / %lu B · tx %lu ops / %lu B\n", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes),
                  static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  }

  void power(const String &arg) {
    long dbm = 0;
    if (!number(arg, -24, 20, dbm)) return warn("power <dBm>, -24 to 20. Now %d dBm", NimBLEDevice::getPower());
    if (!NimBLEDevice::setPower(int8_t(dbm))) return warn("the radio refused %ld dBm", dbm);
    BLE_NOTE(Info, "TX power %d dBm", NimBLEDevice::getPower());
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) < 0x20) {
        // Other control characters (arrow keys send escape sequences): ignore.
      } else if (buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  // RSSI of a live link: the controller measures it on every connection event; we ask once a second.
  void measureRssi() {
    const ble::LinkState &s = link_;
    if (s.radio != ble::Radio::Connected || millis() - rssiAt_ < 1000) return;
    rssiAt_ = millis();
    int8_t rssi = 0;
    if (ble_gap_conn_rssi(s.peer.handle, &rssi) == 0) ble::link().edit([&](ble::LinkState &st) { st.peer.rssi = rssi; });
  }

  // New activity lines go to serial from here, in order, never from the NimBLE task.
  void printActivity() {
    ble::Activity &a = ble::activity();
    const uint32_t head = a.head();
    if (printed_ + ble::Activity::kSize < head) {
      Serial.printf("  ... %lu lines skipped\n", static_cast<unsigned long>(head - ble::Activity::kSize - printed_));
      printed_ = head - ble::Activity::kSize;
    }
    ble::ActEntry e;
    for (; printed_ < head; printed_++)
      if (a.get(printed_, e)) Serial.printf("  %s %s\n", bv::actMark(e.kind), e.text);
  }

  void showLed() {
    if (ledClaimed_) return;
    const uint32_t now = millis();
    const uint32_t traffic = link_.rxOps + link_.txOps;
    if (traffic != traffic_) traffic_ = traffic, flashUntil_ = now + 60;
    // Brightness in 12 steps, so the LED (a whole WS2812 frame per write) is only rewritten on a change.
    const float wave = 0.5f + 0.5f * sinf(now / 1000.0f * 3.1416f);
    const uint8_t breathe = uint8_t(int(wave * 11) * 8 + 6);
    uint8_t r = 0, g = 0, b = 0;
    if (passkeyShowing()) r = (now / 250) & 1 ? 120 : 0, g = r / 2;
    else if (now < flashUntil_) r = 120, g = 120, b = 120;
    else switch (link_.radio) {
      case ble::Radio::Off: break;
      case ble::Radio::Scanning: g = breathe / 2, b = breathe / 2; break;
      case ble::Radio::Advertising: b = breathe; break;
      case ble::Radio::Connecting: r = 60, g = 40; break;
      case ble::Radio::Connected:
        if (link_.peer.encrypted) r = 50, b = 90;
        else b = 90;
        break;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const BleLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  ble::LinkState link_;
  int view_;
  bool ledClaimed_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, flashUntil_ = 0, traffic_ = 0, rssiAt_ = 0, printed_ = 0;
};

// The peripheral side of a link (B3-B7): NimBLE's server callbacks, turned into ble::link() state
// and activity lines. Labs make one, hand it to the server, and override what they need.
//
// Pairing hooks are here too, because every lab after B3 meets them: a passkey to show, a number
// to compare. The passkey goes into the link state; the shell draws it over any view, and the
// button (click = yes, long press = no) or serial `yes`/`no` answers through confirm().
#pragma once

#include <Arduino.h>
#include <NimBLEDevice.h>
#include <esp_random.h>

#include "ble_link.h"

namespace ble {

inline void fillPeer(Peer &p, const NimBLEConnInfo &c) {
  strlcpy(p.addr, c.getAddress().toString().c_str(), sizeof(p.addr));
  const NimBLEAddress id = c.getIdAddress();
  if (!(id == c.getAddress())) strlcpy(p.idAddr, id.toString().c_str(), sizeof(p.idAddr));
  else p.idAddr[0] = 0;
  p.addrType = c.getAddress().getType();
  p.handle = c.getConnHandle();
  p.mtu = c.getMTU();
  p.interval = c.getConnInterval();
  p.latency = c.getConnLatency();
  p.timeout = c.getConnTimeout();
  p.encrypted = c.isEncrypted();
  p.authenticated = c.isAuthenticated();
  p.bonded = c.isBonded();
  p.keySize = c.getSecKeySize();
  p.central = c.isSlave();  // we are the slave (peripheral), so the peer is the central
}

class ServerLink : public NimBLEServerCallbacks {
 public:
  // Advertising starts again by itself after a disconnect (NimBLE's advertiseOnDisconnect).
  void onConnect(NimBLEServer *, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      s.peer = Peer{};
      fillPeer(s.peer, c);
      s.radio = Radio::Connected;
      s.advertising = false;
      s.connections++;
      s.connectedAt = millis();
      s.rxOps = s.txOps = s.rxBytes = s.txBytes = 0;
    });
    BLE_NOTE(Good, "connected: %s", c.getAddress().toString().c_str());
    BLE_NOTE(Info, "interval %.2f ms, latency %u, timeout %u ms", c.getConnInterval() * 1.25f, c.getConnLatency(), c.getConnTimeout() * 10);
  }

  void onDisconnect(NimBLEServer *server, NimBLEConnInfo &c, int reason) override {
    link().edit([&](LinkState &s) {
      s.connections = s.connections ? s.connections - 1 : 0;
      s.radio = advertiseAgain_ ? Radio::Advertising : Radio::Off;
      s.advertising = advertiseAgain_;
      s.lastDisconnect = reason;
      s.passkey = 0;
    });
    BLE_NOTE(Warn, "disconnected 0x%02X: %s", reason & 0xFF, disconnectReason(reason));
    (void)server;
  }

  void onMTUChange(uint16_t mtu, NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { s.peer.mtu = mtu; });
    BLE_NOTE(Info, "MTU %u: %u bytes of data per packet", mtu, mtu - 3);
    (void)c;
  }

  void onConnParamsUpdate(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "new params: %.2f ms, latency %u", c.getConnInterval() * 1.25f, c.getConnLatency());
  }

  void onPhyUpdate(NimBLEConnInfo &c, uint8_t tx, uint8_t rx) override {
    link().edit([&](LinkState &s) { s.peer.txPhy = tx, s.peer.rxPhy = rx; });
    BLE_NOTE(Info, "PHY now %s / %s", tx == 2 ? "2M" : tx == 3 ? "Coded" : "1M", rx == 2 ? "2M" : rx == 3 ? "Coded" : "1M");
    (void)c;
  }

  // ---- Pairing -------------------------------------------------------------------------------

  // Passkey entry, we display: six random digits, the other side types them.
  uint32_t onPassKeyDisplay() override {
    const uint32_t key = esp_random() % 1000000;
    link().edit([&](LinkState &s) { s.passkey = key ? key : 1, s.passkeyCompare = false, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "passkey %06lu: type it on the other device", static_cast<unsigned long>(key));
    return key;
  }

  // Numeric comparison: both screens show the same 6 digits; a person says yes on both.
  void onConfirmPassKey(NimBLEConnInfo &c, uint32_t pin) override {
    pendingHandle_ = c.getConnHandle();
    link().edit([&](LinkState &s) { s.passkey = pin ? pin : 1, s.passkeyCompare = true, s.passkeySince = millis(); });
    BLE_NOTE(Warn, "compare %06lu: same on the phone? (click/yes)", static_cast<unsigned long>(pin));
  }

  void onAuthenticationComplete(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) {
      fillPeer(s.peer, c);
      s.passkey = 0;
    });
    if (c.isEncrypted())
      BLE_NOTE(Good, "secured: %s%s, key %u B", c.isAuthenticated() ? "authenticated" : "Just Works", c.isBonded() ? ", bonded" : "", c.getSecKeySize());
    else
      BLE_NOTE(Bad, "pairing failed: still plain text");
  }

  void onIdentity(NimBLEConnInfo &c) override {
    link().edit([&](LinkState &s) { fillPeer(s.peer, c); });
    BLE_NOTE(Info, "identity: %s", c.getIdAddress().toString().c_str());
  }

  // Answer a numeric comparison (button or serial). False when nothing is waiting.
  bool confirm(bool yes) {
    if (pendingHandle_ == 0xFFFF) return false;
    NimBLEServer *server = NimBLEDevice::getServer();
    if (server) NimBLEDevice::injectConfirmPasskey(server->getPeerInfoByHandle(pendingHandle_), yes);
    pendingHandle_ = 0xFFFF;
    link().edit([&](LinkState &s) { s.passkey = 0; });
    BLE_NOTE(Info, "you said %s", yes ? "yes, it matches" : "no");
    return true;
  }
  bool comparing() const { return pendingHandle_ != 0xFFFF; }

  void setAdvertiseAgain(bool on) { advertiseAgain_ = on; }

 private:
  uint16_t pendingHandle_ = 0xFFFF;
  bool advertiseAgain_ = true;
};

}  // namespace ble

// Drawing pieces every BLE lab shares (320 x 170, landscape):
//   header   "BLE" + the view's name, view dots, and the status cluster: what the radio is doing,
//            a lock when the link is encrypted, a key when the peer is bonded, signal bars
//   footer   the button hint on the left, the latest activity line on the right
//   link     a live connection: who is central, the connection events ticking, MTU, PHY, security
//   log      the activity log, newest at the bottom
//   passkey  the big 6 digits, drawn over any view while pairing waits for you
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include "ble_link.h"
#include "color.h"
#include "frame_buffer.h"

namespace bv {

constexpr int kW = 320, kH = 170, kTop = 30, kBottom = kH - 12;
// Bluetooth's own colours on the bench palette: blue = radio, violet = encrypted.
constexpr uint16_t kBlue = rgb(80, 150, 255);
constexpr uint16_t kViolet = rgb(176, 130, 255);
constexpr uint16_t kPanel = rgb(20, 28, 40);

inline int textWidth(FrameBuffer &fb, const char *s) {
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void small(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(nullptr);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void bold(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

// A label over a value, in a column.
inline void stat(FrameBuffer &fb, int x, int y, const char *label, const char *value, uint16_t c = pal::ink) {
  small(fb, x, y, pal::muted, label);
  bold(fb, x, y + 22, c, value);
}

// Four bars, like a phone's: -50 dBm and up = 4 bars, -90 and below = 0.
inline void signalBars(FrameBuffer &fb, int x, int y, int rssi, uint16_t on = pal::ink) {
  const int bars = rssi == 0 ? 0 : rssi >= -55 ? 4 : rssi >= -67 ? 3 : rssi >= -78 ? 2 : rssi >= -90 ? 1 : 0;
  for (int i = 0; i < 4; i++) {
    const int h = 3 + i * 3;
    fb.fillRect(x + i * 4, y + 12 - h, 3, h, i < bars ? on : pal::dim);
  }
}

inline uint16_t rssiColour(int rssi) { return rssi >= -67 ? pal::teal : rssi >= -82 ? pal::amber : pal::coral; }

inline void lockIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawRoundRect(x + 2, y, 7, 7, 3, c);
  fb.fillRect(x, y + 5, 11, 8, c);
}

inline void keyIcon(FrameBuffer &fb, int x, int y, uint16_t c) {
  fb.drawCircle(x + 3, y + 6, 3, c);
  fb.drawFastHLine(x + 6, y + 6, 7, c);
  fb.drawFastVLine(x + 11, y + 6, 4, c);
  fb.drawFastVLine(x + 9, y + 6, 3, c);
}

// The radio's state as a small animated glyph centred on (x, y).
inline void radioGlyph(FrameBuffer &fb, int x, int y, ble::Radio r, float t) {
  switch (r) {
    case ble::Radio::Off: fb.drawCircle(x, y, 5, pal::dim); break;
    case ble::Radio::Scanning: {
      // A radar sweep: we are listening.
      fb.drawCircle(x, y, 7, pal::dim);
      const float a = t * 5.0f;
      fb.drawLine(x, y, x + int(cosf(a) * 7), y + int(sinf(a) * 7), pal::teal);
      fb.fillCircle(x, y, 1, pal::teal);
      break;
    }
    case ble::Radio::Advertising: {
      // Rings leaving the antenna: we are shouting.
      fb.fillCircle(x, y, 2, kBlue);
      for (int i = 0; i < 2; i++) {
        const float k = fmodf(t * 1.2f + i * 0.5f, 1.0f);
        fb.drawCircle(x, y, 3 + int(k * 6), mix(kBlue, pal::night, uint8_t(k * 255)));
      }
      break;
    }
    case ble::Radio::Connecting:
      fb.drawCircle(x, y, 6, (int(t * 6) & 1) ? pal::amber : pal::dim);
      break;
    case ble::Radio::Connected:
      // Two linked rings: a connection.
      fb.drawCircle(x - 3, y, 4, kBlue);
      fb.drawCircle(x + 3, y, 4, kBlue);
      break;
  }
}

inline void header(FrameBuffer &fb, const char *labId, const char *view, int index, int count, const ble::LinkState &s, float t) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(kBlue);
  fb.setCursor(8, 18);
  fb.print(labId);
  fb.print(" ");
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  // Status cluster, right to left: signal, key, lock, radio.
  int x = 302;
  if (s.radio == ble::Radio::Connected && s.peer.rssi != 0) signalBars(fb, x, 9, s.peer.rssi, rssiColour(s.peer.rssi));
  x -= 18;
  if (s.peer.bonded && s.radio == ble::Radio::Connected) keyIcon(fb, x, 8, pal::amber), x -= 18;
  if (s.peer.encrypted && s.radio == ble::Radio::Connected) lockIcon(fb, x + 2, 7, kViolet), x -= 16;
  radioGlyph(fb, x + 4, 15, s.radio, t);
  const int firstDot = x - 14 - (count - 1) * 9;
  for (int i = 0; i < count; i++) fb.fillCircle(firstDot + i * 9, 15, 3, i == index ? pal::ink : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

inline uint16_t actColour(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return pal::teal;
    case ble::Act::Warn: return pal::amber;
    case ble::Act::Bad: return pal::coral;
    case ble::Act::Rx: return kBlue;
    case ble::Act::Tx: return kViolet;
    default: return pal::muted;
  }
}

inline const char *actMark(ble::Act k) {
  switch (k) {
    case ble::Act::Good: return "+";
    case ble::Act::Warn: return "!";
    case ble::Act::Bad: return "x";
    case ble::Act::Rx: return "<";
    case ble::Act::Tx: return ">";
    default: return "-";
  }
}

// Left: the button hint. Right: the newest activity line, fading after 6 s.
inline void footer(FrameBuffer &fb, const char *hint) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  small(fb, 6, kH - 9, pal::muted, hint);
  ble::Activity &a = ble::activity();
  ble::ActEntry e;
  const uint32_t head = a.head();
  if (head == 0 || !a.get(head - 1, e)) return;
  const uint32_t age = millis() - e.ms;
  if (age > 6000) return;
  char right[30];
  strlcpy(right, e.text, sizeof(right));
  fb.setFont(nullptr);
  const uint16_t c = mix(actColour(e.kind), pal::night, uint8_t(age > 4000 ? (age - 4000) * 200 / 2000 : 0));
  small(fb, kW - 6 - textWidth(fb, right), kH - 9, c, right);
}

// ---- log ----------------------------------------------------------------------------------------

inline void log(FrameBuffer &fb, int y0 = kTop + 4, int rows = 10) {
  ble::Activity &a = ble::activity();
  const uint32_t head = a.head();
  if (head == 0) {
    small(fb, 8, y0 + 4, pal::muted, "Nothing on the air yet.");
    return;
  }
  const uint32_t from = head > uint32_t(rows) ? head - rows : 0;
  ble::ActEntry e;
  int y = y0;
  for (uint32_t i = from; i < head; i++, y += 12) {
    if (!a.get(i, e)) continue;
    char when[12];
    snprintf(when, sizeof(when), "%5lu.%lu", static_cast<unsigned long>(e.ms / 1000), static_cast<unsigned long>(e.ms / 100 % 10));
    small(fb, 4, y, pal::dim, when);
    small(fb, 50, y, actColour(e.kind), actMark(e.kind));
    char text[44];
    strlcpy(text, e.text, sizeof(text));
    small(fb, 60, y, i + 1 == head ? pal::ink : pal::muted, text);
  }
}

// ---- link ---------------------------------------------------------------------------------------

// The connection drawn as two devices and the connection events between them: one exchange every
// interval, the dot's speed is real time slowed down 20x so 7.5-50 ms intervals stay visible.
inline void link(FrameBuffer &fb, const ble::LinkState &s, float t, const char *usLabel = "this board", const char *themLabel = nullptr) {
  const bool up = s.radio == ble::Radio::Connected;
  const int ly = 62, lx = 30, rx = 150;
  fb.fillRoundRect(lx - 22, ly - 22, 44, 44, 6, kPanel);
  fb.drawRoundRect(lx - 22, ly - 22, 44, 44, 6, kBlue);
  fb.fillRoundRect(rx - 16, ly - 26, 32, 52, 6, kPanel);
  fb.drawRoundRect(rx - 16, ly - 26, 32, 52, 6, up ? kBlue : pal::dim);
  small(fb, lx - 18, ly + 28, pal::muted, usLabel);
  small(fb, rx - 18, ly + 28, pal::muted, themLabel ? themLabel : (up && s.peer.name[0] ? s.peer.name : "peer"));
  // Who leads: the central sets the timing, the peripheral answers in each event.
  small(fb, lx - 18, ly - 4, pal::ink, s.peer.central || !up ? "periph" : "central");
  small(fb, rx - 14, ly - 4, up ? pal::ink : pal::dim, s.peer.central ? "central" : "periph");
  if (up) {
    const float intervalMs = s.peer.interval * 1.25f;
    const float period = fmaxf(intervalMs * 20.0f / 1000.0f, 0.15f);
    const float k = fmodf(t, period) / period;
    const int x = lx + 24 + int(k * (rx - lx - 42));
    fb.drawFastHLine(lx + 24, ly - 6, rx - lx - 42, pal::dim);
    fb.drawFastHLine(lx + 24, ly + 6, rx - lx - 42, pal::dim);
    fb.fillCircle(x, ly - 6, 3, s.peer.encrypted ? kViolet : kBlue);
    fb.fillCircle(lx + 24 + (rx - lx - 42) - (x - lx - 24), ly + 6, 3, pal::teal);
    if (s.peer.encrypted) lockIcon(fb, (lx + rx) / 2 - 5, ly - 26, kViolet);
  } else {
    small(fb, lx + 30, ly - 3, pal::muted, s.advertising ? "waiting..." : "no link");
  }

  char v[40];
  const int cx = 190;
  if (!up) {
    stat(fb, cx, 38, "last link ended", s.lastDisconnect < 0 ? "-" : "", pal::muted);
    if (s.lastDisconnect >= 0) {
      snprintf(v, sizeof(v), "reason 0x%02X", s.lastDisconnect & 0xFF);
      bold(fb, cx, 60, pal::ink, v);
      char why[34];
      strlcpy(why, ble::disconnectReason(s.lastDisconnect), sizeof(why));
      small(fb, cx, 68, pal::muted, why);
    }
    return;
  }
  snprintf(v, sizeof(v), "%.2f ms", s.peer.interval * 1.25f);
  stat(fb, cx, 34, "interval", v, kBlue);
  snprintf(v, sizeof(v), "%u B", s.peer.mtu);
  stat(fb, cx + 74, 34, "MTU", v);
  snprintf(v, sizeof(v), "%u", s.peer.latency);
  stat(fb, cx, 70, "latency", v);
  snprintf(v, sizeof(v), "%u ms", s.peer.timeout * 10);
  stat(fb, cx + 74, 70, "timeout", v);
  static const char *const phy[] = {"?", "1M", "2M", "Coded"};
  snprintf(v, sizeof(v), "%s/%s", phy[s.peer.txPhy & 3], phy[s.peer.rxPhy & 3]);
  stat(fb, cx, 106, "PHY tx/rx", v);
  snprintf(v, sizeof(v), "%d dBm", s.peer.rssi);
  stat(fb, cx + 74, 106, "RSSI", s.peer.rssi ? v : "-", s.peer.rssi ? rssiColour(s.peer.rssi) : pal::muted);
  // Security row under the drawing.
  const uint16_t sc = s.peer.encrypted ? kViolet : pal::muted;
  snprintf(v, sizeof(v), "%s%s%s", s.peer.encrypted ? "encrypted" : "plain text", s.peer.authenticated ? " + MITM" : "", s.peer.bonded ? " + bonded" : "");
  small(fb, 8, 114, sc, v);
  snprintf(v, sizeof(v), "%s  up %lus", s.peer.addr, static_cast<unsigned long>((millis() - s.connectedAt) / 1000));
  small(fb, 8, 126, pal::muted, v);
  snprintf(v, sizeof(v), "rx %lu ops %lu B", static_cast<unsigned long>(s.rxOps), static_cast<unsigned long>(s.rxBytes));
  small(fb, 8, 138, kBlue, v);
  snprintf(v, sizeof(v), "tx %lu ops %lu B", static_cast<unsigned long>(s.txOps), static_cast<unsigned long>(s.txBytes));
  small(fb, 8, 148, kViolet, v);
}

