// The Bench service: our own GATT service, met in B3 and reused by B4 and B5.
//
// GATT is a small database on the board. A phone connects, discovers it, and then reads, writes
// or subscribes to its entries (characteristics). Each one has a UUID, properties (read, write,
// notify...) and a value:
//
//   Bench service      ba5e0000-b1e5-4ab1-9e5c-be7cbe7cb0a7
//     LED              ...0001  read, write          3 bytes: red, green, blue
//     Message          ...0002  read, write          up to 40 bytes of UTF-8 text, shown on screen
//     Button           ...0003  read, notify         gesture (1 click, 2 double, 3 long), count (2 B)
//     Temperature      ...0004  read, notify         °C x 100, signed 16-bit (the chip's own sensor)
//     Uptime           ...0005  read                 seconds since power-on, 32-bit
//     Vault (B4)       ...0006  read, write          40 bytes, only over an encrypted, authenticated link
//   Device Information 180A   (standard: who made this)
//   Battery            180F   (standard: 100 %, we're on USB)
//
// Every number is little-endian, like everything else in Bluetooth LE.
#pragma once

#include <Arduino.h>
#include <NimBLE2904.h>
#include <NimBLEDevice.h>

#include "ble_link.h"
#include "server_link.h"

namespace bench {

constexpr const char *kServiceUuid = "ba5e0000-b1e5-4ab1-9e5c-be7cbe7cb0a7";

// "ba5e0001-b1e5-..." for characteristic 1, and so on.
inline NimBLEUUID uuid(uint16_t n) {
  char s[40];
  snprintf(s, sizeof(s), "ba5e%04x-b1e5-4ab1-9e5c-be7cbe7cb0a7", n);
  return NimBLEUUID(s);
}

enum Chr : uint8_t { Led, Message, ButtonChr, Temperature, Uptime, Vault, kChrCount };

inline const char *chrName(int c) {
  static const char *const names[] = {"LED", "Message", "Button", "Temperature", "Uptime", "Vault"};
  return names[c];
}

enum class Op : uint8_t { None, Read, Write, Notify, Subscribe, Denied };

struct Options {
  bool vault = false;         // B4: add the encrypted + authenticated Vault
  bool lockControls = false;  // B4 `lock on`: LED and Message need an encrypted link too
};

// What the screen shows: a copy, taken under the lock.
struct State {
  uint8_t led[3] = {0, 0, 0};
  bool ledWritten = false;
  char message[41] = "";
  uint32_t messageAt = 0;
  float tempC = 0;
  uint16_t buttonCount = 0;
  uint8_t lastGesture = 0;
  char vault[41] = "nothing here yet";
  bool subscribed[kChrCount] = {};
  uint32_t opAt[kChrCount] = {};  // millis() of the last operation, for the pulse on screen
  Op op[kChrCount] = {};
  bool hasVault = false;
};

class BenchService : public NimBLECharacteristicCallbacks {
 public:
  void begin(NimBLEServer *server, const Options &o) {
    opts_ = o;
    state_.hasVault = o.vault;
    NimBLEService *svc = server->createService(kServiceUuid);
    service_ = svc;
    const uint16_t lock = o.lockControls ? (NIMBLE_PROPERTY::READ_ENC | NIMBLE_PROPERTY::WRITE_ENC) : 0;

    chr_[Led] = svc->createCharacteristic(uuid(1), NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::WRITE | lock, 3);
    describe(chr_[Led], "LED colour: red, green, blue");
    chr_[Message] = svc->createCharacteristic(uuid(2), NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::WRITE | NIMBLE_PROPERTY::WRITE_NR | lock, 40);
    describe(chr_[Message], "Message for the screen");
    chr_[ButtonChr] = svc->createCharacteristic(uuid(3), NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY, 3);
    describe(chr_[ButtonChr], "Button: gesture, count");
    chr_[Temperature] = svc->createCharacteristic(uuid(4), NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY, 2);
    describe(chr_[Temperature], "Chip temperature");
    // 2904 = Presentation Format: tells generic apps "signed 16-bit, x 10^-2, degrees Celsius".
    NimBLE2904 *fmt = chr_[Temperature]->create2904();
    fmt->setFormat(NimBLE2904::FORMAT_SINT16);
    fmt->setExponent(-2);
    fmt->setUnit(0x272F);  // degree Celsius
    chr_[Uptime] = svc->createCharacteristic(uuid(5), NIMBLE_PROPERTY::READ, 4);
    describe(chr_[Uptime], "Uptime in seconds");
    NimBLE2904 *up = chr_[Uptime]->create2904();
    up->setFormat(NimBLE2904::FORMAT_UINT32);
    up->setUnit(0x2703);  // second
    if (o.vault) {
      // READ_AUTHEN / WRITE_AUTHEN: encrypted AND paired with protection against a man in the middle
      // (passkey or numeric comparison). A Just Works link is refused.
      chr_[Vault] = svc->createCharacteristic(uuid(6), NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::WRITE | NIMBLE_PROPERTY::READ_ENC |
                                                           NIMBLE_PROPERTY::READ_AUTHEN | NIMBLE_PROPERTY::WRITE_ENC | NIMBLE_PROPERTY::WRITE_AUTHEN,
                                              40);
      describe(chr_[Vault], "Vault (pair first)");
      chr_[Vault]->setValue(state_.vault);
    }
    for (int i = 0; i < kChrCount; i++)
      if (chr_[i]) chr_[i]->setCallbacks(this);
    chr_[Led]->setValue(state_.led, 3);
    chr_[Message]->setValue("");
    const uint8_t button[3] = {0, 0, 0};
    chr_[ButtonChr]->setValue(button, 3);

    // The two standard services, so generic apps show something friendly.
    NimBLEService *dis = server->createService("180A");
    dis->createCharacteristic("2A29", NIMBLE_PROPERTY::READ)->setValue("Hardware Diary bench");
    dis->createCharacteristic("2A24", NIMBLE_PROPERTY::READ)->setValue("ESP32-S3 N16R8");
    dis->createCharacteristic("2A26", NIMBLE_PROPERTY::READ)->setValue("ble-kit 0.1");
    NimBLEService *bat = server->createService("180F");
    NimBLECharacteristic *level = bat->createCharacteristic("2A19", NIMBLE_PROPERTY::READ | NIMBLE_PROPERTY::NOTIFY, 1);
    const uint8_t full = 100;
    level->setValue(&full, 1);
  }

  NimBLEService *service() { return service_; }
  NimBLECharacteristic *characteristic(Chr c) { return chr_[c]; }

  // From loop(): temperature every 2 s (sent only if someone subscribed).
  void tick() {
    if (millis() - tempAt_ < 2000) return;
    tempAt_ = millis();
    const float c = temperatureRead();
    const int16_t centi = int16_t(c * 100);
    chr_[Temperature]->setValue(reinterpret_cast<const uint8_t *>(&centi), 2);
    bool sub;
    portENTER_CRITICAL(&lock_);
    state_.tempC = c;
    sub = state_.subscribed[Temperature];
    portEXIT_CRITICAL(&lock_);
    if (sub && chr_[Temperature]->notify()) noteOp(Temperature, Op::Notify), ble::countTx(2);
  }

  // From loop(): the button. gesture 1 click, 2 double-click, 3 long press.
  void button(uint8_t gesture) {
    uint16_t count;
    bool sub;
    portENTER_CRITICAL(&lock_);
    count = ++state_.buttonCount;
    state_.lastGesture = gesture;
    sub = state_.subscribed[ButtonChr];
    portEXIT_CRITICAL(&lock_);
    const uint8_t v[3] = {gesture, uint8_t(count & 0xFF), uint8_t(count >> 8)};
    chr_[ButtonChr]->setValue(v, 3);
    static const char *const names[] = {"", "click", "double", "long"};
    if (sub && chr_[ButtonChr]->notify()) {
      noteOp(ButtonChr, Op::Notify);
      ble::countTx(3);
      BLE_NOTE(Tx, "notify Button: %s #%u", names[gesture & 3], count);
    } else {
      BLE_NOTE(Info, "button %s #%u (nobody subscribed)", names[gesture & 3], count);
    }
  }

  // Serial `message`: change the value from the board's side too.
  void setMessage(const char *text) {
    chr_[Message]->setValue(text);
    portENTER_CRITICAL(&lock_);
    strlcpy(state_.message, text, sizeof(state_.message));
    state_.messageAt = millis();
    portEXIT_CRITICAL(&lock_);
  }

  State state() {
    portENTER_CRITICAL(&lock_);
    State s = state_;
    portEXIT_CRITICAL(&lock_);
    return s;
  }

  // From loop(): true once per new LED colour written by the phone.
  bool takeLed(uint8_t rgbOut[3]) {
    portENTER_CRITICAL(&lock_);
    const bool fresh = ledFresh_;
    ledFresh_ = false;
    memcpy(rgbOut, state_.led, 3);
    portEXIT_CRITICAL(&lock_);
    return fresh;
  }

  void setVault(const char *text) {
    if (!chr_[Vault]) return;
    chr_[Vault]->setValue(text);
    portENTER_CRITICAL(&lock_);
    strlcpy(state_.vault, text, sizeof(state_.vault));
    portEXIT_CRITICAL(&lock_);
  }

  // ---- NimBLE callbacks (NimBLE task) --------------------------------------------------------

  void onRead(NimBLECharacteristic *c, NimBLEConnInfo &) override {
    const int i = indexOf(c);
    if (i == Uptime) {
      const uint32_t s = millis() / 1000;
      c->setValue(reinterpret_cast<const uint8_t *>(&s), 4);
    }
    noteOp(i, Op::Read);
    ble::countRx(0);
    BLE_NOTE(Rx, "read %s", chrName(i));
  }

  void onWrite(NimBLECharacteristic *c, NimBLEConnInfo &) override {
    const int i = indexOf(c);
    const NimBLEAttValue v = c->getValue();
    ble::countRx(v.size());
    noteOp(i, Op::Write);
    if (i == Led) {
      if (v.size() != 3) return BLE_NOTE(Warn, "LED wants 3 bytes, got %u", v.size());
      portENTER_CRITICAL(&lock_);
      memcpy(state_.led, v.data(), 3);
      state_.ledWritten = true;
      portEXIT_CRITICAL(&lock_);
      ledFresh_ = true;  // loop() lights it (takeLed): only one task ever drives the LED
      BLE_NOTE(Rx, "write LED %02X %02X %02X", v.data()[0], v.data()[1], v.data()[2]);
    } else if (i == Message) {
      char text[41];
      const size_t n = std::min<size_t>(v.size(), 40);
      memcpy(text, v.data(), n);
      text[n] = 0;
      portENTER_CRITICAL(&lock_);
      strlcpy(state_.message, text, sizeof(state_.message));
      state_.messageAt = millis();
      portEXIT_CRITICAL(&lock_);
      BLE_NOTE(Rx, "write Message \"%.30s\"", text);
    } else if (i == Vault) {
      char text[41];
      const size_t n = std::min<size_t>(v.size(), 40);
      memcpy(text, v.data(), n);
      text[n] = 0;
      portENTER_CRITICAL(&lock_);
      strlcpy(state_.vault, text, sizeof(state_.vault));
      portEXIT_CRITICAL(&lock_);
      BLE_NOTE(Rx, "write Vault (%u bytes, encrypted)", n);
    }
  }

  // subValue: 0 off, 1 notifications, 2 indications, 3 both. The phone writes it into the
  // characteristic's CCCD (descriptor 2902).
  void onSubscribe(NimBLECharacteristic *c, NimBLEConnInfo &, uint16_t subValue) override {
    const int i = indexOf(c);
    if (i < 0) return;
    portENTER_CRITICAL(&lock_);
    state_.subscribed[i] = subValue != 0;
    portEXIT_CRITICAL(&lock_);
    noteOp(i, Op::Subscribe);
    BLE_NOTE(Rx, "%s %s (CCCD = %u)", subValue ? "subscribe" : "unsubscribe", chrName(i), subValue);
  }

  // Errors on our own sends. A read or write refused for missing encryption usually never gets
  // here: the NimBLE host checks the permission itself and answers the phone with "Insufficient
  // Authentication" (the phone then starts pairing). Kept for the cases that do arrive.
  void onStatus(NimBLECharacteristic *c, NimBLEConnInfo &, int code) override {
    const int i = indexOf(c);
    if (code == 0 || i < 0) return;
    if (code == BLE_HS_ATT_ERR(BLE_ATT_ERR_INSUFFICIENT_AUTHEN) || code == BLE_HS_ATT_ERR(BLE_ATT_ERR_INSUFFICIENT_ENC)) {
      noteOp(i, Op::Denied);
      BLE_NOTE(Bad, "%s refused: pair first", chrName(i));
    }
  }

 private:
  static void describe(NimBLECharacteristic *c, const char *text) {
    // 2901 = User Description: the name nRF Connect and LightBlue show instead of the UUID.
    c->createDescriptor("2901", NIMBLE_PROPERTY::READ, strlen(text))->setValue(text);
  }

  int indexOf(const NimBLECharacteristic *c) const {
    for (int i = 0; i < kChrCount; i++)
      if (chr_[i] == c) return i;
    return -1;
  }

  void noteOp(int i, Op op) {
    if (i < 0) return;
    portENTER_CRITICAL(&lock_);
    state_.op[i] = op;
    state_.opAt[i] = millis();
    portEXIT_CRITICAL(&lock_);
  }

  Options opts_;
  NimBLEService *service_ = nullptr;
  NimBLECharacteristic *chr_[kChrCount] = {};
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  State state_;
  uint32_t tempAt_ = 0;
  bool ledFresh_ = false;
};

// Advertise the Bench service: flags + the 128-bit service UUID in the advertisement (21 of 31
// bytes), the name in the scan response. Phones filter by the UUID, people read the name.
inline void advertise(const char *name, bool start = true) {
  NimBLEAdvertising *adv = NimBLEDevice::getAdvertising();
  NimBLEAdvertisementData data, response;
  data.setFlags(BLE_HS_ADV_F_DISC_GEN | BLE_HS_ADV_F_BREDR_UNSUP);
  data.addServiceUUID(NimBLEUUID(kServiceUuid));
  response.setName(name);
  response.setAppearance(0x0540);  // generic sensor
  adv->setAdvertisementData(data);
  adv->setScanResponseData(response);
  if (start && adv->start()) {
    ble::link().edit([](ble::LinkState &s) { s.radio = ble::Radio::Advertising, s.advertising = true; });
    BLE_NOTE(Info, "advertising as \"%s\"", name);
  }
}

}  // namespace bench

// What every BLE lab knows about its radio, shared between two tasks.
//
// NimBLE runs its own task (the "host", on core 0). Every callback it makes (a device was heard,
// a phone connected, a value was written) runs there. The screen and serial run in loop() on
// core 1. So the callbacks never draw or print: they update this state and push a line into the
// activity log, and loop() takes a copy to show it. A spinlock guards each copy (a few hundred
// bytes, microseconds), the same idea as the RFID labs' reader snapshot.
#pragma once

#include <Arduino.h>
#include <freertos/FreeRTOS.h>

#include <stdarg.h>

namespace ble {

// What the radio is doing right now, for the status bar and the on-board LED.
enum class Radio : uint8_t { Off, Scanning, Advertising, Connecting, Connected };

inline const char *radioName(Radio r) {
  static const char *const names[] = {"off", "scanning", "advertising", "connecting", "connected"};
  return names[static_cast<int>(r)];
}

// The other side of a connection: a phone, a laptop, a keyboard.
struct Peer {
  char addr[18] = "";        // as the radio sees it right now (may be a private, changing address)
  char idAddr[18] = "";      // the identity address, once bonding revealed it
  char name[24] = "";        // when we know it (scan response, GAP name, or B8's discovery)
  uint8_t addrType = 0;      // 0 public, 1 random
  uint16_t handle = 0xFFFF;  // connection handle
  uint16_t mtu = 23;         // bytes per ATT packet; 23 until both sides agree on more
  uint16_t interval = 0;     // connection interval, in 1.25 ms units
  uint16_t latency = 0;      // events the peripheral may skip
  uint16_t timeout = 0;      // supervision timeout, in 10 ms units
  uint8_t txPhy = 1, rxPhy = 1;  // 1 = 1M, 2 = 2M, 3 = Coded
  int8_t rssi = 0;           // measured on the live connection (0 = not measured yet)
  bool encrypted = false, authenticated = false, bonded = false;
  uint8_t keySize = 0;
  bool central = false;      // true when the PEER is the central (we are the peripheral)
};

struct LinkState {
  Radio radio = Radio::Off;
  bool advertising = false;
  bool scanning = false;
  uint8_t connections = 0;
  Peer peer;                     // the most recent connection
  uint32_t connectedAt = 0;      // millis()
  int lastDisconnect = -1;       // reason code of the last disconnect, -1 = none yet
  uint32_t rxOps = 0, txOps = 0;      // writes/reads received, notifications/indications sent
  uint32_t rxBytes = 0, txBytes = 0;
  uint32_t passkey = 0;          // non-zero while a passkey is on screen (B4, B8)
  bool passkeyCompare = false;   // true = numeric comparison (press to accept), false = type it in
  uint32_t passkeySince = 0;
  uint32_t version = 0;          // bumps on every change
};

// The shared state, one per program. Callbacks call ble::link().edit([](LinkState &s){ ... }).
class Link {
 public:
  template <typename F>
  void edit(F &&change) {
    portENTER_CRITICAL(&lock_);
    change(state_);
    state_.version++;
    portEXIT_CRITICAL(&lock_);
  }
  LinkState get() {
    portENTER_CRITICAL(&lock_);
    LinkState copy = state_;
    portEXIT_CRITICAL(&lock_);
    return copy;
  }

 private:
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  LinkState state_;
};

inline Link &link() {
  static Link l;
  return l;
}

// Every operation that crosses the air, for the traffic counters on the link view.
inline void countRx(size_t bytes) {
  link().edit([&](LinkState &s) { s.rxOps++, s.rxBytes += bytes; });
}
inline void countTx(size_t bytes) {
  link().edit([&](LinkState &s) { s.txOps++, s.txBytes += bytes; });
}

// ---- The activity log ------------------------------------------------------------------------
// Every lab writes what happens on the air here: "→ notify button click", "← write LED ff8000".
// loop() prints new lines to serial and the log view draws the last few.

enum class Act : uint8_t { Info, Good, Warn, Bad, Rx, Tx };

struct ActEntry {
  uint32_t ms = 0;
  Act kind = Act::Info;
  char text[60] = "";
};

class Activity {
 public:
  static constexpr int kSize = 32;

  [[gnu::format(printf, 3, 4)]] void add(Act kind, const char *fmt, ...) {
    ActEntry e;
    e.ms = millis();
    e.kind = kind;
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(e.text, sizeof(e.text), fmt, ap);  // formatted outside the lock
    va_end(ap);
    portENTER_CRITICAL(&lock_);
    ring_[head_ % kSize] = e;
    head_++;
    portEXIT_CRITICAL(&lock_);
  }

  uint32_t head() {
    portENTER_CRITICAL(&lock_);
    const uint32_t h = head_;
    portEXIT_CRITICAL(&lock_);
    return h;
  }

  // Entry number i (0 = the first ever). False when it has already been overwritten.
  bool get(uint32_t i, ActEntry &out) {
    portENTER_CRITICAL(&lock_);
    const bool ok = i < head_ && head_ - i <= kSize;
    if (ok) out = ring_[i % kSize];
    portEXIT_CRITICAL(&lock_);
    return ok;
  }

 private:
  portMUX_TYPE lock_ = portMUX_INITIALIZER_UNLOCKED;
  ActEntry ring_[kSize];
  uint32_t head_ = 0;
};

inline Activity &activity() {
  static Activity a;
  return a;
}

// Short names for the callbacks.
#define BLE_NOTE(kind, ...) ::ble::activity().add(::ble::Act::kind, __VA_ARGS__)

// Why a link ended, in words. NimBLE reports HCI reasons as 0x200 + the HCI code.
inline const char *disconnectReason(int reason) {
  switch (reason & 0xFF) {
    case 0x08: return "timeout: the peer went out of range or stopped answering";
    case 0x13: return "the peer hung up";
    case 0x16: return "we hung up";
    case 0x3B: return "unacceptable connection parameters";
    case 0x3D: return "MIC failure (encryption keys did not match)";
    case 0x3E: return "the connection never got established";
    case 0x05: return "authentication failure (forgotten bond on one side?)";
    case 0x06: return "PIN or key missing (forgotten bond on one side?)";
    default: return "other";
  }
}

}  // namespace ble

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// The 1.9" ST7789 screen plus an off-screen frame buffer, set up the way every lesson since 03 uses it.
// Draw into fb() with the normal Adafruit GFX calls, then push() sends the whole picture at once.
#pragma once

#include <Adafruit_ST7789.h>
#include <SPI.h>

#include "frame_buffer.h"
#include "pins.h"

class Display {
 public:
  static constexpr int16_t kW = 320, kH = 170;  // landscape

  Display() : tft_(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST), fb_(kW, kH) {}

  // Returns false if there is no memory for the frame buffer.
  bool begin(uint32_t spiHz = 40'000'000) {
    // Backlight through PWM so it can be dimmed (setBacklight). Full brightness to start.
    ledcAttach(PIN_TFT_BL, 5000, 8);
    ledcWrite(PIN_TFT_BL, 255);
    SPI.begin(PIN_TFT_SCLK, -1, PIN_TFT_MOSI, PIN_TFT_CS);
    tft_.init(170, 320);
    tft_.setSPISpeed(spiHz);
    tft_.setRotation(1);
    tft_.fillScreen(0);
    return fb_.begin();
  }

  FrameBuffer &fb() { return fb_; }
  // 0 = off, 255 = full brightness.
  void setBacklight(uint8_t level) { ledcWrite(PIN_TFT_BL, level); }
  void push() { tft_.drawRGBBitmap(0, 0, fb_.pixels(), kW, kH); }

 private:
  Adafruit_ST7789 tft_;
  FrameBuffer fb_;
};

// The one place that says which wire goes where.
// Change a number here (or pass -DPIN_xxx=N as a build flag) and every lesson follows.
//
// Pins to keep away from on the ESP32-S3-N16R8:
//   0, 3, 45, 46   strapping pins: they decide how the chip boots
//   19, 20         native USB D- / D+
//   26-32          wired to the flash chip
//   33-37          wired to the octal PSRAM (that's the "R8" in N16R8)
//   43, 44         UART0 TX / RX: the serial monitor on the "COM" port
#pragma once

// On-board addressable RGB LED (WS2812). Most N16R8 DevKitC clones use 48;
// v1.1 boards use 38. If lesson 01 shows no colour, try 38.
#ifndef PIN_RGB
#define PIN_RGB 48
#endif

